const page = (title, body) => '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FRUiTIFY</title><style>body{font-family:Arial,sans-serif;max-width:620px;margin:24px auto;padding:0 16px;color:#222}textarea{width:100%;box-sizing:border-box;font-size:16px;padding:10px;border:1px solid #ccd;border-radius:8px}button{background:#1f7a4a;color:#fff;border:0;padding:12px 22px;border-radius:8px;font-size:16px}.box{background:#f5f5f5;padding:10px;border-radius:8px;white-space:pre-wrap}</style></head><body><h2 style="color:#1f5f3f">' + title + '</h2>' + body + '</body></html>';
const esc = s => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');

const q = $('Review opened').first().json.query || {};
if (q.k !== '<APPROVAL_KEY>') return [{ json: { html: page('Link not valid', '') } }];
const row = $('Read CRM (page)').all().map(r => r.json).find(r => String(r.Instagram).toLowerCase() === String(q.u || '').toLowerCase());
if (!row || !row['IG user id']) return [{ json: { html: page('Not found', '<p>This person has no Instagram chat with us yet.</p>') } }];
if (!String(row['Next reply draft'] || '').trim()) return [{ json: { html: page('Already sent ✓', '<p>This reply to <b>' + esc(row.Name || row.Instagram) + '</b> has already been sent. Nothing more to do.</p>') } }];
const last = String(row['Vendor reply'] || '').split('\n---\n').pop();
const body = '<p><b>' + esc(row.Name || row.Instagram) + '</b> (@' + esc(row.Instagram) + ')</p><p>They wrote:</p><div class="box">' + esc(last) + '</div>' +
  '<form method="POST" style="margin-top:16px" onsubmit="var b=this.querySelector(\'button\');b.disabled=true;b.textContent=\'Sending… please wait\';"><input type="hidden" name="k" value="' + esc(q.k) + '"><input type="hidden" name="u" value="' + esc(row.Instagram) + '"><input type="hidden" name="c" value="' + esc(q.c || '') + '">' +
  '<p><b>Your reply</b> (you can change any word)</p><textarea name="m" rows="7">' + esc(row['Next reply draft']) + '</textarea>' +
  '<p><label style="font-size:16px"><input type="checkbox" name="v" value="1" checked style="width:20px;height:20px;vertical-align:middle"> Also send our 1-minute FRUiTIFY video</label></p><p><button>Send on Instagram</button></p></form><p style="color:#888;font-size:13px">Sent from fruitify.india.byanay. Instagram allows replies within 24 hours of their last message.</p>';
return [{ json: { html: page('Review and send', body) } }];

const b = $('Send confirmed').first().json.body || {};
const row = $('Read CRM').all().map(r => r.json).find(r => String(r.Instagram).toLowerCase() === String(b.u || '').toLowerCase());
const ok = b.k === '<APPROVAL_KEY>' && row && row['IG user id'] && String(b.m || '').trim();
const draft = row ? String(row['Next reply draft'] || '').trim() : '';
const log = row ? String(row['Vendor reply'] || '') : '';
let commentId = String(b.c || '');
if (b.via === 'chat' || (commentId && log.includes('(c:' + commentId + ')'))) commentId = '';
return [{ json: { ok: !!ok && !!draft, already: !!ok && !draft, u: row ? row.Instagram : '', name: row ? (row.Name || row.Instagram) : '', igid: row ? String(row['IG user id']) : '', text: String(b.m || '').trim(), commentId: commentId, lang: row ? String(row.Language || '') : '', withVideo: String(b.v || '') === '1', log: row ? row['Vendor reply'] : '' } }];

const page = (title, body) => '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FRUiTIFY</title><style>body{font-family:Arial,sans-serif;max-width:620px;margin:24px auto;padding:0 16px;color:#222}textarea{width:100%;box-sizing:border-box;font-size:16px;padding:10px;border:1px solid #ccd;border-radius:8px}button{background:#1f7a4a;color:#fff;border:0;padding:12px 22px;border-radius:8px;font-size:16px}.box{background:#f5f5f5;padding:10px;border-radius:8px;white-space:pre-wrap}</style></head><body><h2 style="color:#1f5f3f">' + title + '</h2>' + body + '</body></html>';
const esc = s => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');

const c = $('Check').first().json;
if (c.already) return [{ json: { html: page('Already sent ✓', '<p>This reply was already sent earlier, so it was NOT sent again.</p>') } }];
if (!c.ok) return [{ json: { html: page('Could not send', '<p>The link was not valid or the message was empty.</p>') } }];
const s = $('Merge send result').first().json;
if (s.message_id) return [{ json: { html: page('Sent ✓', '<p>Your reply was sent to <b>' + esc(c.name) + '</b> on Instagram' + (c.withVideo ? ', together with our FRUiTIFY video' : '') + '.</p><p style="color:#888;font-size:13px">You can close this page.</p>') } }];
const b0 = $('Send confirmed').first().json.body || {};
const err = (s.error && (s.error.message || JSON.stringify(s.error))) || JSON.stringify(s).slice(0, 300);
return [{ json: { html: page('Not confirmed', '<p>Instagram did not confirm this message (' + esc(err).slice(0, 160) + ').</p><p><b>Instagram sometimes delivers it anyway.</b> First open the chat with <b>' + esc(c.name) + '</b> in the Instagram app and check.</p><p>Only if it is NOT there, tap the button below to send it into the chat once.</p><form method="POST" onsubmit="var x=this.querySelector(\'button\');x.disabled=true;x.textContent=\'Sending…\';"><input type="hidden" name="k" value="' + esc(b0.k) + '"><input type="hidden" name="u" value="' + esc(c.u) + '"><input type="hidden" name="via" value="chat"><input type="hidden" name="v" value="' + (c.withVideo ? '1' : '') + '"><textarea name="m" rows="6">' + esc(c.text) + '</textarea><p><button>Send into chat</button></p></form>') } }];
